import type { CharacterDatabase, ElementType, HSRCharacter, PathType } from '../types/hsr';
import generated from './generated/characters.json';

/**
 * Generated by `npm run data` from prydwen.gg (builds, relics, teams) and
 * StarRailRes (element, Path, rarity, base stats, art). Do not hand-edit —
 * re-run the generator instead.
 */
export const CHARACTER_DB = generated as unknown as CharacterDatabase;

export const CHARACTERS: HSRCharacter[] = CHARACTER_DB.characters;

const BY_ID = new Map(CHARACTERS.map((character) => [character.id, character]));

export function getCharacter(id: string): HSRCharacter | undefined {
  return BY_ID.get(id);
}

/** Throws for ids that are not in the roster — use for known-good defaults. */
export function requireCharacter(id: string): HSRCharacter {
  const character = BY_ID.get(id);
  if (!character) throw new Error(`Unknown character: ${id}`);
  return character;
}

export const ELEMENTS: ElementType[] = [
  'Physical',
  'Fire',
  'Ice',
  'Lightning',
  'Wind',
  'Quantum',
  'Imaginary'
];

export const PATHS: PathType[] = [
  'Destruction',
  'The Hunt',
  'Erudition',
  'Harmony',
  'Nihility',
  'Preservation',
  'Abundance',
  'Remembrance',
  'Elation'
];

/** Highest-ranked Memory of Chaos team Prydwen records for this character. */
export function bestTeam(character: HSRCharacter) {
  return character.teams.length
    ? character.teams.reduce((best, team) =>
        (team.rank ?? Infinity) < (best.rank ?? Infinity) ? team : best
      )
    : null;
}
